  def tokenize(value: Any): Token = {
    val strValue = value match {
      case f: Float => f"%.${precision}f".format(f)
      case d: Double => f"%.${precision}f".format(d)
      case i: Int => i.toString
      case l: Long => l.toString
      case b: BigDecimal => f"%.${precision}f".format(b)
      case n: Number => n.toString
      case other => other.toString
    }

    val originalType = value match {
      case null => "NoneType"
      case _ => value.getClass.getSimpleName
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> originalType))
  }
}

class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  private val ISO_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE_TIME
  private val DATE_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE

  def tokenize(value: Any): Token = {
    val strValue = value match {
      case ldt: LocalDateTime =>
        formatStr match {
          case Some(fmt) => ldt.format(DateTimeFormatter.ofPattern(fmt))
          case None => ldt.format(ISO_FORMAT)
        }
      case ld: LocalDate =>
        formatStr match {
          case Some(fmt) => ld.format(DateTimeFormatter.ofPattern(fmt))
          case None => ld.format(DATE_FORMAT)
        }
      case other => other.toString
    }
    Token(strValue, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Universal Tokenizer
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: Any): Token = {
    if (value == null) return Token("NULL", TokenType.NULL)

    value match {
      case t: Tokenizable => Token(t.toToken, TokenType.STRUCTURED)
      case s: String => stringTokenizer.tokenize(s)
      case b: Array[Byte] => stringTokenizer.tokenize(b)
      case i: Int => numericTokenizer.tokenize(i)
      case d: Double => numericTokenizer.tokenize(d)
      case f: Float => numericTokenizer.tokenize(f)
      case l: Long => numericTokenizer.tokenize(l)
      case bd: BigDecimal => numericTokenizer.tokenize(bd)
      case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
      case d: LocalDate => temporalTokenizer.tokenize(d)
      case _ => Token(value.toString, TokenType.STRING, Map("fallback" -> true))
    }
  }

  // Method required by TokenizerSpec.scala
  def tokenizeNull: Token = tokenize(null)
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

class TokenRegistry[T] {
  private val _registry = mutable.Map[String, TokenContainer[T]]()
  private val _handlers = mutable.ListBuffer[T => Option[Token]]()

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry(key) = container
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.map { item =>
          var result: Option[Token] = None
          val iter = _handlers.iterator
          while (result.isEmpty && iter.hasNext) {
            result = iter.next()(item)
          }
          result
        }.toList
    }
  }
}

// ============================================================================
// Higher-Kinded Type Simulation
// ============================================================================

class TokenFunctor[T](val value: T) {
  def map[B](func: T => B): TokenFunctor[B] = {
    new TokenFunctor(func(value))
  }

  def flatMap[B](func: T => TokenFunctor[B]): TokenFunctor[B] = {
    func(value)
  }

  def get: T = value
  def getOrElse(default: T): T = if (value != null) value else default
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[B](funcWrapped: TokenMonad[T => B]): TokenMonad[B] = {
    new TokenMonad(funcWrapped.value(value))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.").toList

    def navigate(c: io.circe.ACursor, p: List[String]): io.circe.ACursor = p match {
      case Nil => c
      case head :: tail =>
        val next = if (head.forall(_.isDigit)) c.downN(head.toInt) else c.downField(head)
        navigate(next, tail)
    }

    val resultCursor = navigate(value.hcursor, parts)
    resultCursor.focus.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer
// ============================================================================

class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = ".,!?;:'\"()[]{}"

  private def processToken(word: String): Option[String] = {
    var w = word
    if (stripPunctuation) {
      w = w.dropWhile(c => punctuation.contains(c)).reverse.dropWhile(c => punctuation.contains(c)).reverse
    }
    if (lowercase) {
      w = w.toLowerCase
    }

    if (w.length < minLength) return None

    maxLength match {
      case Some(max) if w.length > max => w = w.substring(0, max)
      case _ =>
    }

    if (w.isEmpty) None else Some(w)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+")
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer[(String, Int, Int)]()
    var currentPos = 0
    val words = text.split("\\s+")

    for (word <- words) {
      val start = text.indexOf(word, currentPos)
      if (start != -1) {
        val end = start + word.length
        processToken(word).foreach { processed =>
          result += ((processed, start, end))
        }
        currentPos = end
      }
    }
    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Builder Pattern
// ============================================================================

class TokenizerBuilder[T] {
  private val _normalizers = mutable.ListBuffer[String => String]()
  private val _validators = mutable.ListBuffer[T => Boolean]()
  private var _metadata = Map[String, Any]()

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    _normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    _validators += validator
    this
  }

  def withMetadata(meta: (String, Any)*): TokenizerBuilder[T] = {
    _metadata ++= meta
    this
  }

  def build(): T => Token = {
    val normalizers = _normalizers.toList
    val validators = _validators.toList
    val metadata = _metadata

    (value: T) => {
      // Validate
      for (validator <- validators) {
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString

      // Normalize
      for (normalizer <- normalizers) {
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, metadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
